insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 1, 'The Heat Exchanger and Cooling Studio puts three tabs over one exchanger. Which four questions does the engine behind those tabs answer about that unit?', '["What duty the streams exchange, what pressure each side drops, what coefficient the surface carries, and how many tubes and baffles the shell needs.", "What duty the two streams exchange, what driving force they exchange it across, what coefficient the surface carries, and how much surface and how many tubes that takes.", "What duty the streams exchange, what driving force they cross, what the shell side works out at from stream analysis, and what the bundle vibrates at.", "What the two streams exchange at their terminals, how much deposit has settled on the surface since the unit was commissioned, what the fan costs to turn, and how many tubes the bundle holds."]'::jsonb, 1, 'Four questions, and then the engine rates a machine you already have in both directions and sizes an air cooler. A pressure drop, a stream-analysis shell side and a vibration check are all outside this module.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 2, 'A flowsheet asks this engine for the tube-side pressure drop through the bundle it has just sized. What comes back?', '["Nothing, because no pressure drop of any kind is computed here. Pressure drop in a line belongs to the Pipeline and Line Sizing engine.", "The tube count door returns it beside the count, because the count and the velocity through the bundle are both in hand by that point.", "A named string on the error key, the way an unknown arrangement is refused, because the routine is present and wants a friction factor supplied to it.", "A figure carried straight through from the input that supplied it, in the way the shell-side film coefficient is carried, since both are quantities a caller types."]'::jsonb, 0, 'This is an absence rather than a refusal. A pressure drop is not computed, not refused and not typed here, because the question belongs to another engine in the package.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 3, 'Twelve exports in this module share one calling and answering contract. What is it?', '["Each is called with its arguments in the order the studio lists them, and each answers with a bare number or a NaN.", "Each is called with a named-argument object, and answers with an object or a bare number according to the answer.", "Each is called with a single named-argument object, each answers with an object, and each refusal puts a named string on an error key.", "Each is called with a named-argument object, and signals a refusal by throwing, which the studio catches once at the boundary of the tab that made the call."]'::jsonb, 2, 'One contract at twelve doors, so one guard shape works everywhere. A caller reads the error key, and a refusal arrives in the same shape as an answer.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 4, 'This module exports seventeen names and twelve of them are the doors the studio calls. What are the other five?', '["Five frozen tables: the declared constants, the declared bounds, the held register, the bundle constants and the air density table.", "Three more callable exports and two frozen tables, with the held register kept private to the module.", "Two frozen tables and three helpers reached only through the doors above them.", "Two more callable exports, which are the documented exceptions to the object contract, and three frozen tables."]'::jsonb, 3, 'The three tables are the declared constants, the declared bounds and the held-for-literature register. The two extra callables are the air density and the bundle constants.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 5, 'The air density export answers with a bare number rather than with an object. What does it do when it has no answer, and why is it written that way?', '["It hands back a zero, which the bay reads as a density no air can have and reports onward as a named refusal of its own.", "It hands back a bare NaN, because a bare number has nowhere to put an error key, and its one caller turns that NaN into a named refusal.", "It throws, and the air cooler door catches the throw and converts it into the named string a caller of that door expects to read.", "It hands back the density at the standard barometric base, so that a caller always has a number to carry forward into a volume."]'::jsonb, 1, 'The module documents the exception rather than making it silently. A leaf correlation has nowhere to put an error key, so the contract is kept one level up, where a caller can see it.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 6, 'What does the bundle constants export take as an argument, and what does it hand back?', '["No argument at all, and a copy of the held bundle table.", "A layout angle and a pass count, and the one constant pair that those two inputs select out of the table.", "A named-argument object carrying the layout, and a named string on an error key when the layout is one it does not carry.", "No argument at all, and the declared constants table, which is where the bundle figures are kept."]'::jsonb, 0, 'It is the second documented exception to the object contract. It takes nothing and returns a copy of the held table, so a caller can read what the module cannot source.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 7, 'Two doors in this module answer with thirteen keys each and two answer with one. Which is the wide pair, and what makes an answer that wide?', '["The tube count and the tube-side film, each of which carries a full geometry back with the figure that was asked for.", "The energy balance and the log mean, because a duty and a driving force each carry their terminals, their basis and their notes.", "The air cooler and the overall coefficient, and both assemble something out of parts, so the parts come back beside the total.", "The air cooler and the tube count, because a bay and a bundle are the two answers in this module that describe a piece of hardware."]'::jsonb, 2, 'A capacity rate and an area carry one key each, because each is a single number with no parts. The tube count and the tube-side film carry ten.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 8, 'On the probes the teaching digest runs, three of the twelve doors handed back more than a message when they refused. What were the extra keys?', '["The defaults the door would have substituted had it been willing to answer the call at all.", "The nearest input value that would have been accepted, so a caller can see how far outside the band the study sits.", "The intermediate figures the door had already reached at the moment it stopped computing.", "The numbers that produced the state the door refused."]'::jsonb, 3, 'A refusal carrying its evidence lets an interface show why a state is impossible rather than only that it is. Three of twelve is what those probes measured, so read it as a floor.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 9, 'What is a refusal message in this module built to let a reader do?', '["Reproduce the arithmetic that failed, because it prints every intermediate figure the engine reached before it stopped.", "Find the box to change, because it names the input that is wrong, quotes the value given and says what that input means.", "Judge how far outside the band a study sits, because it prints the nearest acceptable value beside the value that was given.", "Decide whether the guard is worth overriding, because it states which of the checks a caller that knows better may relax."]'::jsonb, 1, 'A message reading only that the balance is infeasible would be true and useless. Somebody with a saved study open needs to know which box to change.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 10, 'The overall coefficient this module reports names its reference area on every answer. Which area is it, and why does the module say so every time?', '["The inside tube surface, because the tube-side film is the term most callers want to read back off the coefficient.", "The bare bundle surface, because a finned bay and a plain bundle report their coefficients on two different surfaces.", "The outside tube surface, because a second export in this package is referred to a stated bore instead, so a figure carried between the two is wrong by the ratio of the areas.", "The outside tube surface, because the area a tube count returns is an inside surface, so a caller has to reconcile the two."]'::jsonb, 2, 'A coefficient without its reference area is not a number you can use. The words the engine prints are outside tube surface (do), and the per-tube surface a count uses is an outside surface too.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 11, 'Why does this course print resistances to nine decimals when it prints temperatures, coefficients and percentages to six?', '["Because the interesting resistances are small, and one rounded to six decimals loses the term a reader is trying to see.", "Because a resistance is known to nine figures, while a temperature is only ever measured well enough to justify six.", "Because a resistance is a reciprocal, so it needs three more places to carry the accuracy of the coefficient it came from.", "Because the grader will accept a resistance only at nine decimals, and a course prints figures at the precision its grader demands."]'::jsonb, 0, 'These are reporting conventions and not claims about accuracy. Duties, capacity rates and the UA product print to four decimals and counts are whole numbers, on the same footing.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 12, 'The word fouling appears in this course and in the Separation course. What is the relationship between the two uses?', '["They are the same quantity reached two ways, so a figure from either course may be carried into the other once the two areas agree.", "Here it is the percentage a coefficient loses as a surface dirties, and there the same percentage is applied to the capacity of a separator.", "Here it is the mass of deposit on a tube in lb per ft2, and there it is the pressure drop that deposit adds across a mesh pad.", "They are different quantities. Here it is a heat-transfer resistance in hr.ft2.F per Btu that sits as a term in the coefficient, and there it is a mist extractor fouling."]'::jsonb, 3, 'Different units and a different remedy, sharing one word. Check which of the two a document means before carrying a number out of it.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 13, 'Where does the letter P belong in this course?', '["It is the probability band a figure sits in, written the way a percentile is written across the rest of the platform.", "It is a dimensionless temperature group and it is nothing else here.", "It is the pressure term the air cooler balance carries, which is the one place pressure enters this module at all.", "It is the temperature group on the sizing side and a percentile on the rating side, so a reader checks which tab produced it."]'::jsonb, 1, 'Nothing in heat exchange here is a percentile, so no P ten and no P fifty belongs anywhere near these answers.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 14, 'The shell-side film coefficient is not worked out anywhere in this module. What happens to it instead?', '["It is refused with a named string whenever a caller asks for it, so only an overall coefficient may be typed.", "It is computed from the shell diameter and the baffle spacing the bundle answer returns.", "It stays an input, and the module says plainly that it carries no shell-side film from stream analysis.", "It is taken as equal to the tube-side film until a caller types a better figure."]'::jsonb, 2, 'Absent and stated, which is the honest shape. Boiling, condensation, fin geometry, vibration and a rigorous cross-flow rating are outside this module on the same terms.'),
  ('heattransfer', 'beginner', 'module', 'm01-what-this-engine-rates', 15, 'A caller writes one guard that covers all twelve doors. What is it checking, and what does it do when the check fires?', '["It reads the error key, and where that key is present it treats the rest of the answer as not to be trusted.", "It reads the number of keys on the answer, and where the count is below what that door normally returns it retries the call.", "It checks each returned figure for a NaN, since that is how this module reports a state it will not compute.", "It checks the sign of the headline figure, since a refusal here arrives as a negative surface or a negative duty."]'::jsonb, 0, 'Nothing in this module returns a NaN in place of a number at these twelve doors, and nothing hands back a negative surface and leaves a caller to notice.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 1, 'A capacity rate is a mass flow multiplied by a heat capacity. What does an energy balance keep of a stream once that multiplication is done?', '["The mass flow as well, since the balance needs it again to place the duty on the right side of the exchanger.", "Nothing else at all. The capacity rate is the whole of what the balance knows about that stream.", "The heat capacity as well, to be re-applied once the duty is known.", "The fluid the stream is made of, because the balance carries it through to the film and the fouling allowance later."]'::jsonb, 1, 'Two streams with the same capacity rate behave identically in every equation in this module, whether one is a lot of a fluid with a small heat capacity or a little of one with a large heat capacity.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 2, 'The studio hot stream runs 50000.0000 lb an hour at 0.550000 Btu per lb per degF. What is its capacity rate, and in what units?', '["2750000.0000 Btu an hour per degF.", "27500.0000 Btu an hour per lb per degF.", "50000.0000 Btu an hour per degF, since the heat capacity is a property rather than a rate.", "27500.0000 Btu an hour per degF."]'::jsonb, 3, 'A mass flow times a heat capacity, and the units follow the multiplication: lb an hour times Btu per lb per degF is Btu an hour per degF.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 3, 'Two streams carry different mass flows and different heat capacities and arrive at the same capacity rate. What can any equation in this module use to tell them apart?', '["Nothing at all, because the balance keeps only the product, and every equation downstream of it reads that product rather than the two figures behind it.", "The heat capacity, which the engine reads again at the outlet temperature.", "The temperature change each one shows, since a heavier flow moves more slowly for a given duty.", "The basis key, which names the stream the balance worked from."]'::jsonb, 0, 'The studio cold stream is 80000.0000 lb an hour at 1.000000 Btu per lb per degF and the studio hot stream 50000.0000 at 0.550000. Each one reaches the balance as one number, and the multiplication throws the rest away on purpose.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 4, 'The studio case gives two capacity rates, two inlet temperatures and a hot outlet of 200.000000 degF against a hot inlet of 300 F. What does the balance produce from that, and in which order?', '["The cold outlet first, at 134.375000 degF, and then the duty from the cold rise, at 2750000.0000 Btu an hour.", "The duty and the cold outlet together from one expression, at 2750000.0000 Btu an hour and 134.375000 degF, since neither is derived from the other.", "The duty first, at 2750000.0000 Btu an hour, and then the cold outlet from that duty, at 134.375000 degF.", "The duty alone, at 2750000.0000 Btu an hour, with the cold outlet left to a later door."]'::jsonb, 2, 'One stated outlet gives the hot drop, the hot drop and the hot capacity rate give the duty, and that duty divided by the cold capacity rate of 80000.0000 Btu an hour per degF gives the cold rise. Three numbers came out of one.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 5, 'The balance answers with five keys and one of them is the basis. What does the basis key say?', '["Which arrangement the duty was computed under, so a reader knows whether a parallel test or a counter test was applied to it.", "Which of the three statings the engine worked from, in words, so the reading is reported rather than inferred.", "Which of the two streams governs the balance, which is the one whose temperature moves furthest for the duty.", "Which of the four terminal temperatures the engine treated as fixed while it iterated the other three."]'::jsonb, 1, 'On the studio case it reads hot outlet. Two people with the same screen open can disagree about a duty entirely because one typed a cold outlet and the other typed a hot one, and this key ends that argument.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 6, 'On the studio streams, the hot outlet, the cold outlet and the duty are each stated in turn. What moves across those three answers?', '["Only the basis, which reads hot outlet, then cold outlet, then stated duty. The duty and both outlet temperatures are the same in all three.", "The duty is the same in all three at 2750000.0000 Btu an hour, and the outlet that was not stated moves a little in each case.", "Nothing moves at all, including the basis, because the engine reports the stating it prefers rather than the one it was given.", "The duty moves between the three statings, because a stated duty is taken as given while a stated outlet is worked through the capacity rates."]'::jsonb, 0, 'The duty is 2750000.0000 Btu an hour, the hot outlet 200.000000 degF and the cold outlet 134.375000 degF on every one of the three rows. They are three views of one state.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 7, 'A study states a duty of 3200000 Btu/hr on the studio hot stream and a hot outlet of 200 F at the same time. What does the balance do?', '["It answers on the stated duty, because a duty is the more direct input of the two and the outlet is then recomputed from it.", "It answers on the stated outlet, because a terminal temperature outranks a duty here.", "It refuses, and quotes back the 183.6364 F that duty would leave the stream at beside the 200 F that was given.", "It answers with the duty the two inputs imply between them, which is the midpoint of the duty stated and the duty the outlet sets."]'::jsonb, 2, 'Stating two of the three is an assertion that they agree, and the engine checks the assertion rather than picking a winner. Choosing silently would make the answer depend on a rule nobody wrote down.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 8, 'Why does the engine refuse that pair rather than preferring one of the two figures?', '["Because the two figures are in different units, and the module converts nothing silently anywhere.", "Because a duty stated beside an outlet is outside the band of the guard that runs first, and every guard in the balance refuses rather than clamping.", "Because the check is cheaper than the arithmetic, so a disagreement is caught before any division has been done.", "Because a silent preference makes an answer depend on a rule that is written down nowhere, and a reader cannot tell afterwards which figure was used."]'::jsonb, 3, 'The message works the outlet the stated duty implies, prints it beside the outlet typed, and tells the reader to state one of them.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 9, 'ORON states its hot outlet, the same basis as the studio case. What comes out of its balance?', '["A duty of 5046800.0000 Btu an hour, with its cold stream leaving at 134.375000 degF.", "A duty of 5046800.0000 Btu an hour, with its cold stream leaving at 167.515873 degF.", "A duty of 2750000.0000 Btu an hour, with its cold stream leaving at 167.515873 degF.", "A duty of 5046800.0000 Btu an hour, with its hot stream leaving at 167.515873 degF."]'::jsonb, 1, 'ORON is the four-pass exchanger this course carries beside the studio case. The two share nothing but the method, so no figure from one belongs in the other.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 10, 'On the studio case the hot capacity rate is 27500.0000 and the cold one 80000.0000 Btu an hour per degF. Which stream''s temperature moves further, and why?', '["The cold stream, because the larger capacity rate absorbs more Btu an hour and so travels further in temperature.", "Whichever stream is stated, because the stated outlet fixes one change and the other follows from the duty.", "The hot stream, because the same duty passes through both and the smaller capacity rate needs more degrees to carry it.", "Neither, because the two changes are equal by the balance and only their starting temperatures differ."]'::jsonb, 2, 'The hot stream falls from 300 F to 200.000000 degF while the cold rises from 100 F to 134.375000 degF. That follows from one duty dividing by two different capacity rates.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 11, 'The engine reports a capacity ratio of 0.343750 on the studio case. How is it formed, and what does that fix about it?', '["The smaller capacity rate over the larger, which is why it is never above one.", "The hot capacity rate over the cold one, which is why it is below one whenever the cold stream is the larger.", "The cold rise over the hot drop, which is why it is dimensionless and never above one.", "The governing capacity rate over the duty, which is why it carries the units of a reciprocal temperature."]'::jsonb, 0, 'It is 27500.0000 over 80000.0000 on this case. Defined smaller over larger, so the definition rather than the case is what keeps it at or below one.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 12, 'Where does the capacity ratio enter the chain this tier walks?', '["In the area, which is the duty over the coefficient, the correction factor and the capacity ratio.", "In the log mean, because the ratio decides which two ends the driving force is built from.", "In the tube count, because the ratio sets how many passes a bundle needs to carry the governing stream.", "Nowhere. Sizing asks for a duty, a driving force and a coefficient, and never asks which stream is the smaller."]'::jsonb, 3, 'Knowing which stream governs is where the rating question begins, and rating belongs to a later tier. This tier identifies the governing stream and carries its capacity rate forward.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 13, 'ORON''s hot stream is 45880.0000 and its cold stream 110880.0000 Btu an hour per degF. What may a reader write down about ORON from those two figures?', '["That the hot stream governs, and that ORON''s capacity ratio is the smaller figure divided by the larger.", "That the hot stream is the smaller one and so the governing one, and no more than that.", "That the cold stream governs, being the one carrying the most heat.", "That neither governs until the duty is known, because the governing stream depends on which outlet was stated."]'::jsonb, 1, 'The direction is readable straight off the capacity rate table. This course does not print a capacity ratio for ORON, because the engine was not asked for one there, and a figure made by dividing two columns is a figure nothing in this module stands behind.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 14, 'What simplification is inside every capacity rate in this module?', '["That the mass flow is the same at both ends of the exchanger, which fails as soon as any fluid leaks.", "That the two streams have the same heat capacity, which is what lets one duty serve both sides.", "That the heat capacity is constant across the whole temperature range of the exchanger.", "That the heat capacity was measured on the fluid rather than taken from a table of similar fluids."]'::jsonb, 2, 'A real fluid''s heat capacity moves with temperature and this module does not track that. A stream changing phase, or one whose heat capacity moves a lot between inlet and outlet, is a case where the simplification is worth naming.'),
  ('heattransfer', 'beginner', 'module', 'm02-the-stream-and-its-capacity-rate', 15, 'The capacity rate has a door of its own. What does it answer with, and what does it refuse?', '["An object carrying one key, the capacity rate, and it refuses a non-positive mass flow with a named string.", "An object carrying three keys, the capacity rate and the two figures it was formed from, and it refuses a heat capacity above one.", "A bare number, which is the documented exception to the object contract in this module, and it refuses nothing at all.", "An object carrying one key, and it answers a zero mass flow with a zero rather than refusing."]'::jsonb, 0, 'One key, because a capacity rate is a single number with no parts. A stream that is not flowing is not a stream the balance can use, so a non-positive flow is refused rather than answered with a zero.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 1, 'A study gives the studio streams a hot outlet of 320 F against a hot inlet of 300 F. What happens, and what does the message say?', '["It is answered with a negative duty, which the studio renders in red so a reader can see the direction is wrong.", "It is refused. The message quotes both temperatures and says an exchanger takes heat out of this stream.", "It is refused, and the message names the duty the two temperatures imply so a reader can see how far out the study is.", "It is answered, because a hot outlet above a hot inlet is a heating case and the balance carries both directions."]'::jsonb, 1, 'The guard runs before any arithmetic, so the message can quote only the inputs, which is exactly what the person reading it has to change.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 2, 'What would have reached a surface if that wrong-way outlet had not been guarded?', '["A duty of zero, because the balance would have clamped the drop at nothing rather than letting it go the wrong way.", "A refusal one door further down, at the log mean, which cannot take a negative end difference and would have caught it there.", "A negative hot drop, a negative duty with it, and a cold outlet below the cold inlet, every one of which prints perfectly well.", "An infinite surface, because a negative duty divided by a positive driving force cannot produce a usable area."]'::jsonb, 2, 'A negative duty in a report looks like a sign convention rather than a mistake, which is why the check runs before the computation rather than after it.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 3, 'A cold outlet of 94 F is given against a cold inlet of 100 F. Why does the module carry this guard separately from the hot-side one?', '["Because the balance can be reached through either outlet, so each stating needs its own check.", "Because the two guards quote different units, and a module that converts nothing silently needs one guard for each.", "Because the cold side is checked after the duty has been computed and the hot side before it.", "Because only the cold outlet can be stated as a target, so its guard is the one a saved study reaches."]'::jsonb, 0, 'A module guarding only the stating it expected people to use would pass the other one straight through. The message here says an exchanger puts heat into this stream.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 4, 'A stated duty arrives as 0. What does the balance do, and why is a zero worth a guard of its own?', '["It answers with a surface of zero, which is the arithmetically correct answer to a duty of nothing and does no harm downstream of it.", "It refuses, because a zero duty would divide by zero in the area and produce an infinite surface.", "It substitutes the duty the stated outlets imply, since a zero can only mean the box was left empty.", "It refuses and quotes the zero back, because an empty box and a cleared field both look like a zero by the time they reach a number."]'::jsonb, 3, 'A zero or a negative duty is not an exchanger. The difference between a refusal and a zero duty carried quietly onward is the difference between a question and a wrong answer with a surface attached to it.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 5, 'A duty is asked for that would leave the studio hot stream at -45.45 F and the cold stream at 218.75 F. What is wrong with that state?', '["The hot outlet is below zero on the Fahrenheit scale, which is outside the band the balance carries.", "The two outlets are on the wrong sides of each other, which parallel flow cannot deliver although a counter-current unit can.", "The hot stream would be cooled below the 100 F cold inlet and the cold stream heated above the 300 F hot inlet, so the two would have to pass through each other.", "The duty exceeds what the smaller capacity rate can carry across the span between the two inlets at any arrangement."]'::jsonb, 2, 'Between the two inlet temperatures is the only range either stream can end up in while heat flows one way. No exchanger of any size does what this duty asks.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 6, 'That refusal carries two extra keys beside the message. What are they called and what do they hold?', '["thOut and tcOut, holding -45.454545 and 218.750000 degF, which are the outlet temperatures this exchanger would run at once it reached the stated duty.", "thOutIfReached and tcOutIfReached, holding -45.454545 and 218.750000 degF, which are the temperatures the duty asked for would imply.", "dt1 and dt2, holding the two end differences the duty implies, which is what makes the crossing visible.", "thOutIfReached and tcOutIfReached, holding the nearest pair of outlets that would have been accepted."]'::jsonb, 1, 'The names are conditional on purpose. Those are not temperatures anywhere in any exchanger, and they are handed back so a caller can show why a state is impossible rather than only assert it.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 7, 'The message on that refusal says -45.45 F while the key beside it reads -45.454545. Which do you use, and what is the rule?', '["The key. A message is rounded for reading, so a figure scraped out of one carries the sentence''s rounding into whatever it is used for.", "The message, because it is the figure the engine chose to publish and the keys are internal.", "Either, because the two agree to the precision this course prints and a rounding at that depth cannot reach an area.", "The key on a refusal and the message on an answer, because only a refusal carries figures at full precision."]'::jsonb, 0, 'The same rule holds on the answers and not only on the refusals. If you need the figure, read the key.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 8, 'Why does the crossing refusal name no area, no coefficient and no arrangement?', '["Because the guard runs before the area door has been called, so those figures do not exist yet.", "Because the message is deliberately kept short, and every number a caller needs is carried on the two evidence keys that sit beside it.", "Because an arrangement is only ever named where a test for that arrangement was applied, and this refusal comes before any such test has been reached.", "Because none of them would help. A bigger exchanger drives the outlets further apart in the same direction and makes the crossing worse."]'::jsonb, 3, 'This refusal is about the two streams and nothing else. It differs from the parallel refusal exactly there, because that one ends by naming the arrangement that can deliver the duty.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 9, 'A duty of 5200000 Btu an hour is asked of the studio streams in parallel flow. What comes back?', '["An answer, at 5200000.0000 Btu an hour, carrying a note that says the parallel arrangement is close to the limit of what it can deliver.", "A refusal that names no figures, because parallel flow is infeasible here whatever the temperatures work out at.", "A refusal, with the two outlet temperatures it would take, 110.909091 and 165.000000 degF, handed back as evidence.", "A refusal, with the two inlet temperatures quoted, since those are what bound a parallel-flow duty."]'::jsonb, 2, 'The message says the two streams would leave at 110.91 F hot and 165.00 F cold, so they must have crossed inside, and that a counter-current unit can take this duty.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 10, 'The same duty of 5200000 Btu an hour is put to a counter-current unit. What comes back, and how does it compare with the evidence on the parallel refusal?', '["An answer of 5200000.0000 Btu an hour with outlets of 110.909091 and 165.000000 degF, which is the parallel evidence figure for figure.", "An answer at a lower duty, because a counter-current unit reaches these terminals only by moving less heat than was asked for in the first place.", "An answer carrying the same two outlet temperatures in the other order, since counter-current flow pairs each inlet with the other stream''s outlet.", "A refusal of its own, because a duty that puts the hot outlet below the cold outlet would do that in either of the two arrangements."]'::jsonb, 0, 'The balance had worked out both outlet temperatures before it decided to refuse. The computation is the same computation, and only the test applied to its result changed.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 11, 'Why can parallel flow not take the hot outlet below the cold outlet at any area?', '["Because the parallel log mean is fixed by the two inlet temperatures alone, so the outlets of a parallel unit cannot move once its inlets are set.", "Because both streams leave at the same end, so the two are still in contact there and the hot one cannot have got below the cold one.", "Because the parallel pairing puts the two inlets together at one end, and a pairing built that way leaves no room at all for a crossing.", "Because a parallel unit is a single pass, and the outlets of one pass are fixed entirely by the two inlets that the pass started from."]'::jsonb, 1, 'In counter-current flow the streams enter at opposite ends, so the leaving hot stream meets the entering cold stream at 100 F and is free to go below the cold outlet, which it never meets.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 12, 'The arrangement is given as Parallel, with a capital letter, on the studio terminals. What is the log mean?', '["130.064846 degF, because an unrecognised string falls back to the default arrangement, which is counter.", "120.584840 degF, and the answer carries a note naming the arrangement it matched the string to.", "120.584840 degF, which is the parallel figure, because case and the spaces around the word do not decide which method runs.", "A refusal, because the module matches its arrangements exactly and Parallel is not one of the three it carries."]'::jsonb, 2, 'An arrangement arriving from a dropdown, a saved file or somebody''s typing all reach the same place. The counter-current figure on those same four temperatures is 130.064846 degF.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 13, 'An arrangement of crossflow is given. What does the module do?', '["It refuses and names the door and the check that rejected the string, so a caller can go and read the rule for themselves.", "It answers on the counter-current pairing and reports its basis as counter, so the substitution is visible on the answer.", "It answers and attaches a note saying a cross-flow correction has not been applied to the figure.", "It refuses, names counter, parallel and shell1 as what it carries, and states that it will not fall back to one of them."]'::jsonb, 3, 'Two things are done at once. The list saves a trip to the source, and the stated policy of not substituting tells a reader something about every other answer this module gives.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 14, 'Suppose the module fell back to counter-current flow instead of refusing an arrangement it does not carry. What would that cost on the studio terminals?', '["You would have received 120.584840 degF, which is the parallel figure, since a fallback takes the lower of the two driving forces available on those four terminals.", "You would have asked for cross flow and received 130.064846 degF, in range and plausible and the counter-current figure under another name.", "Nothing on these terminals, because the two pairings agree to within the precision this course prints.", "You would have received a refusal one door later, at the area, where a driving force from an unknown arrangement is caught."]'::jsonb, 1, 'Compare it with the parallel figure of 120.584840 degF on the same four temperatures and the size of the gap a silent fallback would hide is visible. A refusal costs a minute.'),
  ('heattransfer', 'beginner', 'module', 'm03-the-refusals-that-protect-a-balance', 15, 'What makes the arrangement part of the question rather than a label on the answer?', '["The test the balance applies is the test for the arrangement it was given, so changing the word changes which states are reachable.", "The arrangement decides which of the two capacity rates governs the balance, so it changes the duty itself before any test is applied to it.", "The arrangement is carried on the answer as the basis key, and that key is what each later door reads when it picks the method to run.", "The arrangement fixes the correction factor, which multiplies the driving force and so moves every duty a unit can reach."]'::jsonb, 0, 'There is no single feasibility check here that both arrangements share. Ask under parallel flow and the parallel test runs, and a study whose arrangement was set once and never looked at again can refuse duties the machine on the plot would deliver.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 1, 'In counter-current flow, which two temperature differences is the log mean built from?', '["The two inlets paired together and the two outlets paired together, which is the pairing at each end of the unit.", "The hot inlet paired with the hot outlet, and the cold inlet with the cold outlet, which are the two spans the streams travel.", "Each inlet paired with the other stream''s outlet, because the hot stream enters where the cold stream leaves.", "The largest and the smallest of the four differences that can be formed among the terminals of the exchanger."]'::jsonb, 2, 'On the studio terminals that gives a hot inlet of 300 F facing a cold outlet of 134.375000 degF, which is 165.625000 degF, and a hot outlet of 200.000000 degF facing a cold inlet of 100.000000 degF, which is 100.000000 degF.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 2, 'The studio case in parallel flow has end differences of 200.000000 and 65.625000 degF. What is its log mean, and how does it compare with the counter-current figure on the same four temperatures?', '["120.584840 degF, below the counter-current 130.064846 degF.", "132.812500 degF, above the counter-current 130.064846 degF.", "130.064846 degF, the same as the counter-current figure, since both pairings use all four terminals.", "120.584840 degF, above the counter-current 130.064846 degF, because the parallel ends are further apart."]'::jsonb, 0, 'One end got wider and the other got much narrower, and the mean came out below the counter-current one. The log mean is pulled down hard by the narrow end.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 3, 'What is the relationship between a log mean and the arithmetic mean of the same two ends?', '["The log mean is strictly below it in counter-current flow and strictly above it in parallel flow.", "The log mean is strictly below it whenever the ends differ, and equal to it when they do not.", "The log mean is below it whenever the ends are more than about ten degF apart and equal within that.", "The log mean is below it on every case the module carries, which is a measurement rather than a limit."]'::jsonb, 1, 'That is an analytic limit rather than a result of the code. It needs no publication, so a reader can check it on any row of any table in this course.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 4, 'The studio case has an arithmetic mean of 132.812500 degF in counter-current flow and 132.812500 degF in parallel flow. Why are those two the same figure?', '["Because the arithmetic mean is taken across the two inlet temperatures, and those two do not move at all when the arrangement changes.", "Because an arithmetic mean is reported only once for a case, on the arrangement the engine worked from.", "Because the two pairings are the same pairing written in the other order, so nothing about them differs.", "Because half the sum of the two ends is the same in both pairings, since both use all four terminals with the same signs."]'::jsonb, 3, 'Only the log mean tells the two arrangements apart, at 130.064846 degF counter and 120.584840 degF parallel, which alone should stop anybody using an arithmetic mean as a driving force.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 5, 'Published case 6 has ends of 300.000000 and 10.000000 degF. Its log mean is 85.264090 degF and its arithmetic mean 155.000000 degF. What does that row show?', '["That two ends as far apart as these put the log mean far below the arithmetic mean, while equal ends put the two together.", "That the log mean approaches the smaller of the two ends as they separate, which is the reason it lands near 10.000000 degF on this row.", "That an arithmetic mean may be used where the ends are close and must be avoided beyond about a hundred degF.", "That the published cases were chosen to bracket the studio case, which sits between them on both means."]'::jsonb, 0, 'Read it against published case 3, where both ends are 280.000000 degF and the two means are the same number. The direction is what the table shows, and this course goes no further with it.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 6, 'Both ends of published case 3 are 280.000000 degF. What does the closed form do there, and what does the engine return?', '["The closed form returns the arithmetic mean instead, which at equal ends is also 280.000000 degF.", "The closed form is evaluated one digit either side of the equality and the two results are averaged.", "The closed form would divide zero by zero, so the module handles the case directly and returns a log mean of 280.000000 degF.", "The closed form refuses, because a ratio of one has a logarithm of zero and nothing can be divided by it."]'::jsonb, 2, 'As the two ends approach each other the log mean approaches their common value, so at equal ends it is that value. The equal-ends flag on that answer reads yes.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 7, 'The log mean answer carries an equal-ends flag. On which answers does it appear?', '["Only where the two ends are equal, which is its purpose, so its absence is what tells a caller the general branch ran.", "Only on the counter-current readings, because equal ends can arise there and cannot arise in parallel flow.", "On every answer except a refusal, where the two end differences are handed back in its place instead.", "On every one. It reads no on the studio case and on ORON in both pairings, and yes on published case 3."]'::jsonb, 3, 'A caller never has to decide whether two ends were close enough to worry about. The engine has already decided and publishes the decision.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 8, 'An exchanger with equal ends is not a contrived input. When does it arise in counter-current flow?', '["When the two streams are the same fluid, so the same heat capacity appears on both sides of the balance.", "When the hot drop equals the cold rise, which is when the two capacity rates are equal.", "When the duty is at the largest value the two streams can exchange, which closes both ends at once.", "When the arrangement is shell1, because a shell pass and two tube passes make the two ends meet."]'::jsonb, 1, 'That is why it deserves a flag rather than a guard. It is a case an engineer will actually meet.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 9, 'The shell1 reading is asked for on the studio terminals. What number comes back, and what basis is reported?', '["130.064846 degF, with the basis reported as counter, because that is the pairing the engine ran.", "120.584840 degF, with the basis reported as shell1, since a shell exchanger pairs its ends the parallel way.", "130.064846 degF, with the basis reported as shell1, because the arrangement asked for is the one reported back.", "A figure between the two pairings, with the basis reported as shell1, since a 1-2 shell unit is part counter and part parallel."]'::jsonb, 0, 'The engine reports the method it ran rather than the arrangement you asked about. Those are two different facts and it publishes the one that matters for checking.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 10, 'What does the note on the shell reading tell a caller about the figure beside it?', '["That the counter-current pairing was substituted because the shell pairing is not carried, so the figure should be treated as approximate.", "That a 1-2 shell exchanger is rated on the counter-current log mean multiplied by F, so the figure returned is one multiplication short of a corrected driving force.", "That the figure is the corrected driving force already, with the correction applied silently at this door.", "That a shell exchanger needs a second log mean taken across its second tube pass before any surface can be sized."]'::jsonb, 1, 'It is a note rather than a refusal, because the counter-current log mean genuinely is the first half of what a shell exchanger is rated on. A silent answer would be worse, because the figure looks finished.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 11, 'A caller takes 130.064846 degF from the shell reading and puts it straight into a surface. What has gone wrong?', '["The surface has been sized on the parallel pairing, so it comes out larger than the counter-current answer would be.", "Nothing has gone wrong yet, because the correction factor is applied at the area door rather than at this one.", "The surface has been sized on a driving force larger than the one the unit will run at, so it comes out smaller than it should be.", "The surface carries the units of the shell reading rather than of an area, so the figure is not an area at all."]'::jsonb, 2, 'The number is right. The use of it is wrong, and the note is sitting there saying so. A correction factor is at or below one, so the corrected driving force is at or below the figure returned.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 12, 'A log mean is asked for with only three of the four terminal temperatures. What comes back?', '["A refusal saying an input is missing, without naming which one.", "An answer built on the three terminals given, with the fourth worked out from the duty and the capacity rates.", "A refusal that names the missing terminal and offers the value it would take if the duty were held fixed.", "A refusal that names the missing terminal, saying tcOut was not given."]'::jsonb, 3, 'Naming the terminal is the difference between a message you can act on and a message you have to investigate. A log mean is built from four temperatures by subtraction and cannot be worked out from a duty.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 13, 'A counter-current log mean is asked for on a pair of streams whose two ends have both closed to zero. What comes back, and what rides beside it?', '["An answer of 0.000000 degF, since a driving force of nothing is a legitimate answer to a pair of closed ends.", "A refusal naming a temperature cross, with the two end differences dt1 and dt2 beside it at 0.000000 and 0.000000 degF.", "A refusal naming a temperature cross, with the four terminal temperatures beside it so a caller can see which one closed the ends.", "A refusal naming a division by zero, since the logarithm is what fails first and the message reports the arithmetic."]'::jsonb, 1, 'An end difference of zero means the two streams have reached the same temperature at that end, and a negative one means they have passed each other. Neither can be fed to a logarithm.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 14, 'Why does that cross refusal name the arrangement it was working in?', '["Because the arrangement decided which two ends were formed, and a pair of terminals that crosses in one pairing need not cross in the other.", "Because every message in this module names an arrangement, so that a saved study can be reconstructed from its messages.", "Because the cross is tested only in counter-current flow, and the name tells a reader the test was run.", "Because the arrangement is what the caller most often has wrong, so the message names it before the temperatures."]'::jsonb, 0, 'The two ends are formed by the pairing, so which differences went to zero depends on the word the caller gave.'),
  ('heattransfer', 'beginner', 'module', 'm04-the-log-mean-driving-force', 15, 'Six rows of the log mean table carry a golden figure. What is a golden figure there?', '["The engine''s answer recorded a second time, kept in a file so a change to the code shows up as a difference.", "A published measurement from a plant test, which is what makes those six rows the evidence in this table.", "The oracle''s own answer, reached by integrating the driving force rather than by evaluating a closed form.", "The figure the closed form gives at the published inputs, rounded to the precision this course prints at."]'::jsonb, 2, 'A golden figure beside an engine figure is two methods meeting. Even so it has a blind spot: a check comparing a formula against a file written from the same formula cannot see an error made in both, and the analytic limit covers exactly that.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 1, 'What goes into the surface an exchanger needs, and what does not?', '["The duty divided by the coefficient and the log mean, with the correction factor applied afterwards to the tube count.", "The duty divided by the coefficient, the correction factor and the log mean. No geometry, no fluid and no allowance beyond those.", "The duty divided by the coefficient, the correction factor, the log mean and the capacity ratio of the smaller stream to the larger one.", "The duty divided by the clean coefficient and the log mean, with the fouling allowances added to the surface as a margin."]'::jsonb, 1, 'On the studio case that is 2750000.0000 Btu an hour over a coefficient of 92.110348, a correction factor of 1.000000 and a log mean of 130.064846 degF, which is 229.543151 ft2.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 2, 'An area comes off the screen at half what you expected. What does the form of the expression tell you about where to look?', '["There are exactly four places, because the area is proportional to the duty and inversely proportional to each of the other three, so an error in any one arrives in the area unchanged.", "There is one place, the coefficient, because it is the only figure in the expression a person did not compute.", "There are four places, but an error in the log mean is damped by the logarithm inside it and so arrives smaller than it started.", "There is no way to tell from the expression, because the four figures were produced by four doors and any of them may carry a compounded error."]'::jsonb, 0, 'No averaging, no damping and nothing in the expression to absorb an error. Three of the four can be checked independently by reopening the doors that produced them.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 3, 'The studio case is sized on its clean coefficient of 134.459410 and on its dirty coefficient of 92.110348 Btu an hour per ft2 per degF. What two areas come out, and which one is bought?', '["157.246707 ft2 clean and 229.543151 ft2 dirty, and the clean one is bought, with the dirty figure kept as a check.", "229.543151 ft2 clean and 157.246707 ft2 dirty, and the dirty one is bought because it is the smaller.", "157.246707 ft2 clean and 229.543151 ft2 dirty, and the dirty one is bought.", "157.246707 ft2 clean and 232.477856 ft2 dirty, and the dirty one is bought."]'::jsonb, 2, 'The larger coefficient asks for the smaller surface. The exchanger has to do its duty when it is dirty, so a unit sized on 157.246707 ft2 would fall short as soon as anything settled on a tube.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 4, 'What is the clean coefficient good for, if the surface is bought on the dirty one?', '["It is the figure a fabricator works to, because a new exchanger is clean on the day it is built.", "It sets the two fouling allowances, since a pair of allowances is chosen to hold a fixed ratio between the clean figure and the dirty one.", "It bounds the error in the dirty figure, because the true coefficient of a running unit lies between the two.", "It says what the machine can do at its best, which is what a performance check on a freshly cleaned unit is compared against."]'::jsonb, 3, 'The difference between the two is two allowances a person chose, which makes the dirty coefficient and every area out of it a number with a judgement inside it. Write the allowances down beside the area.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 5, 'The area door is given a coefficient of 0. What comes back?', '["A refusal naming the coefficient: the area needs a positive overall coefficient, and it was 0 Btu/hr.ft2.F.", "An area of zero, since nothing passes through a surface that carries no coefficient at all.", "A refusal naming the duty, because a zero coefficient is only reachable when the duty behind it was zero too.", "The clean area instead, since a coefficient of zero is read as an instruction to size the unit before fouling."]'::jsonb, 0, 'That is a division by zero waiting to happen, and an infinite surface is not an answer anybody can act on.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 6, 'The area door is given a correction factor of 1.000001. What happens, and why is the band closed at one?', '["It refuses and quotes the value back, because a correction factor is only ever read off a published chart and no such chart runs above one.", "It refuses and quotes the value back, because a factor above one would say an arrangement beats counter-current flow at the same terminals.", "It rounds the figure to 1.000000 and answers, because the difference is below the precision this course prints at.", "It answers and attaches a note, because a factor slightly above one is within the tolerance the module declares."]'::jsonb, 1, 'Refusing at a millionth over the boundary looks fussy until you remember what a factor slightly above one would do to a surface, which is to make it slightly too small for a reason nobody would ever find.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 7, 'How is the surface of one tube formed?', '["Pi times the mean of the inside and the outside diameter times the length, which is the surface that the wall term of the coefficient is referred to.", "Pi times the outside diameter squared times the length over four, which is the volume the tube encloses divided by the bore that carries the flow.", "Pi times the outside diameter times the length, with the diameter divided by twelve because it is given in inches and the length in feet.", "Pi times the inside diameter times the length, because the tube-side fluid is what the surface is there to carry."]'::jsonb, 2, 'There is no judgement anywhere in this step. There is no correlation, no exponent and no fitted constant, so if the diameter and the length are right then the figure is right.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 8, 'The seven tube-count cases in this course show only two per-tube surfaces, 3.141593 and 5.235988 ft2. What does that tell you?', '["That the module carries two tube sizes and refuses any other, which is why every case lands on one of them.", "That a per-tube surface is quantised by the bundle constants, which carry two sizes across their four pass counts.", "That the duty decides the tube size, and these seven duties fall into two bands.", "Something about the cases rather than about the engine, since each was set up on one of two tube sizes."]'::jsonb, 3, 'A per-tube surface is fixed the moment a diameter and a length are chosen, and nothing about the duty, the streams or the coefficient reaches it.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 9, 'Why must the diameter in the per-tube surface be the outside diameter?', '["Because the area being divided is an outside tube surface, which follows from the coefficient it came from being referred to the outside tube surface.", "Because the outside surface is the larger of the two, so using it is the conservative choice at this step.", "Because the tube-side film is computed on the bore, and the two would be counted twice if the bore were used here as well.", "Because the bundle constants are written against outside diameters, so a count formed on the bore would not fit the layout."]'::jsonb, 0, 'Use an inside diameter by mistake and the per-tube surface comes out smaller, so the count comes out larger. The error is quiet, because a larger count looks conservative rather than wrong.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 10, 'The first of the two roundings takes the count up to a whole tube rather than to the nearest one. Why up?', '["Because the second rounding can only ever lift the count further, so a count rounded down at the first step would be lifted back by the second one anyway.", "Because a count rounded down gives a bundle whose surface is below the surface the duty asked for, so the unit would be short of duty by construction.", "Because a fraction of a tube is always taken up to a whole tube in this module, in exactly the way that a fraction of a pass is taken up to a whole pass.", "Because rounding to the nearest whole tube would make the overshoot negative on about half of all cases, and a negative margin is not something this module reports."]'::jsonb, 1, 'Rounding up can only give more surface than was needed. On the studio case the area over one tube rounds up to 74.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 11, 'The second rounding takes the count up to a whole multiple of the pass count. What does it buy beyond a bundle that can be built?', '["A count that divides into the bundle constants, which this module carries for 1, 2, 4 and 6 tube passes and for no other number of passes at all.", "A count whose overshoot comes out positive, which is something that the first of the two roundings cannot guarantee on its own on any given case at all.", "A count that can be fed back into the tube-side film, because a count the passes do not divide has no tubes a pass to compute a velocity from.", "A count that matches the golden file, which is written at whole multiples of the pass count on every one of the published cases this course carries."]'::jsonb, 2, 'On the studio case the passes are 2 and the count is 74, so 37 tubes go in each pass. On ORON the passes are 4 and the count is 64, so 16 go in each.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 12, 'On the studio case the area over one tube rounds up to 74 and the engine returns 74 tubes in 2 passes. What does that row show about the second rounding?', '["That it moved the count up from the unrounded figure to 74, which is why the tubes a pass come out at 37.", "That it ran first here, because a count that the passes divide is rounded to the passes before it is rounded to a whole tube.", "That it is applied only where the pass count is above two, which is why ORON shows it and the studio case does not.", "That it had nothing to do on this row, since 2 divides 74 already, so the row cannot show you the second rounding at all."]'::jsonb, 3, 'Published case 3 is a row where it does show. At 1200.000000 ft2 on tubes of 5.235988 ft2 in 4 passes the count comes out at 232, at 58 a pass, and only the second rounding moved it.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 13, 'The studio case asks for 229.543151 ft2 and its 74 tubes carry 232.477856 ft2, an overshoot of 1.278498 percent. Why can that percentage never be negative?', '["Because both roundings go up, so the count sits at or above the unrounded figure and the actual area sits at or above the area asked for.", "Because the module reports the overshoot as an absolute value, so the sign carries no information.", "Because the area asked for is itself a rounded figure, and the rounding in it is always downward.", "Because a negative margin would be refused by the tube count door before the answer was assembled."]'::jsonb, 0, 'An overshoot of zero needs the unrounded figure to be a whole number that the pass count divides, which is rare. Every figure in that column of the seven cases is positive.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 14, 'Published case 2 has 638 tubes at an overshoot of 0.216806 percent and published case 4 has 274 tubes at 0.092603 percent. What does that pair rule out?', '["That the first of the two roundings is what sets the margin, since both of those rows are two-pass bundles.", "That a larger bundle always overshoots less, since here the smaller bundle overshot less.", "That the overshoot depends on the pass count, since both of those rows are two-pass bundles.", "That the two roundings are independent, since a single rounding would have put these two rows in order."]'::jsonb, 1, 'Where the overshoot lands depends on where the fraction fell. Read the column as seven separate answers and do not divide one by another.'),
  ('heattransfer', 'beginner', 'module', 'm05-the-surface-and-the-tubes', 15, 'Why does this tier check the rounding through the margin rather than through the tube count?', '["Because the count is the figure the engine computes last, so an error anywhere upstream reaches the margin first.", "Because two different counts can produce the same margin, which makes the margin the wider of the two checks.", "Because a count is a whole number, so a check on it is exact or out by a whole tube, while the margin moves the instant either rounding moves the count.", "Because the margin is reported to six decimals and a count is reported as a whole number, so the margin carries more digits."]'::jsonb, 2, 'A margin that comes out right cannot have been reached with a wrong count. The reverse does not hold, because two different unrounded figures can round to the same count, so a matching count leaves you none the wiser.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 1, 'What makes the studio default case the one case in this course a reader can check outside the course?', '["It is the only case carried through every one of the doors of this module, so nothing in it has to be taken on trust.", "It is the case the Heat Exchanger and Cooling Studio opens with, so every figure in it is on a live screen.", "It is the case the golden file was written from, so a reader can check every line of it against the published rows.", "It is the case the capstone is set on, so a reader meets the same figures twice and can compare them."]'::jsonb, 1, 'ORON and the published cases are worked here on the page. The studio case is worked on a screen as well, which is a second place to check it.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Multiply the studio coefficient of 92.110348 by the area required of 229.543151 ft2, by the correction factor of 1.000000 and by the log mean of 130.064846 degF. What is the figure, and what has been shown?', '["2750000.0000 Btu an hour, which is the duty, so the coefficient has been confirmed by a route independent of the one that produced it.", "2750000.0000 Btu an hour, which is the duty, so the tube count has been shown to have converged.", "A figure above the duty by the area overshoot, so the margin the rounding left is visible in the check itself.", "2750000.0000 Btu an hour, which is the duty, so the four figures on the screen satisfy the equation the area came out of."]'::jsonb, 3, 'It is the same equation run backwards, which is exactly why it is useful: if four figures on a screen do not reproduce the duty, one of them has been left behind by an input that moved.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Why does that check use the area required rather than the actual area of 232.477856 ft2?', '["Because the actual area is larger, having been rounded up, so multiplying it through gives more than the duty.", "Because the actual area is a whole number of tubes multiplied out, and the check is defined on continuous figures.", "Because the actual area belongs to the bundle rather than to the balance, and the two are reported by different doors.", "Because the actual area carries the fouling allowance already, so using it would count the fouling twice."]'::jsonb, 0, 'That is the overshoot arriving where you may not expect it. On this case it is 1.278498 percent, and the check would miss the duty by exactly that.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Which four links form the loop in this chain?', '["The duty needs a driving force, the driving force needs an arrangement, the arrangement needs a count, and the count needs a duty.", "The area needs a log mean, the log mean needs the outlets, the outlets need a duty, and the duty needs an area.", "The film needs a tube count, the count needs an area, the area needs the coefficient, and the coefficient needs the film.", "The count needs a bundle diameter, the bundle needs a shell, the shell needs a clearance, and the clearance needs a count."]'::jsonb, 2, 'There is no first link, which is what makes it a loop rather than a line. The film needs how fast the fluid is going, and that depends on how many tubes it is shared between.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 5, 'A circle of dependencies usually needs a solver. Why does this one settle under plain iteration?', '["Because the count is a whole number, so there are finitely many states available and the loop has to revisit one of them in the end.", "Because each pass raises the count, so the loop is monotone and stops at the first count that is large enough.", "Because the studio picks a seed close to the answer, so the loop has little distance to travel before it settles.", "Because the map is a contraction, so a count that goes round once comes out closer to the answer than the one that went in."]'::jsonb, 3, 'No solver, no bisection and no derivative. The trail is worth watching settle, and the studio shows it.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 6, 'The studio walks a seed ladder of 2, 12, 60 and 300 tubes rather than starting from a single count. What is the ladder for?', '["A single seed can be too far from the answer for the iteration to converge, and a ladder brackets the answer instead.", "A single seed can land in the band the film refuses to answer in, and a loop that cannot take its first step has no answer at all.", "A ladder lets the studio report how sensitive the converged count is to where the loop was started from.", "A ladder is how the module checks that the count is unique, since every rung has to arrive at the same answer."]'::jsonb, 1, 'The film door has a band in which no correlation this module carries applies, and it says so rather than guessing. The first seed that evaluates is the one that starts the loop.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Every rung of the studio ladder is a multiple of 2 and every rung of ORON''s ladder of 4, 24, 120 and 600 is a multiple of 4. Why?', '["Because a seed has to be a multiple of the tubes a pass, which on those two cases are 37 and 16.", "Because the ladder rungs are spaced by a factor that has to divide the pass count for the loop to be stable.", "Because those are the pass counts, and a seed the pass count does not divide is a count the bundle cannot have.", "Because the bundle constants are carried for 1, 2, 4 and 6 passes, so every seed has to be a multiple of one of those."]'::jsonb, 2, 'The studio case runs 2 passes and ORON runs 4. A multi-pass bundle puts the same number of tubes in every pass, so a seed that does not divide equally is not a bundle.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What is the trail on the studio case, and how many passes of the loop did it take?', '["2, 60, 72 and 74 tubes, converged in 4 passes.", "2, 12, 60 and 300 tubes, converged in 4 passes.", "2, 60, 72, 74 and 74 tubes, converged in 5 passes, the last one repeating the answer.", "60, 72 and 74 tubes, converged in 3 passes, since the first rung is a seed rather than a step."]'::jsonb, 0, 'The seed ladder is 2, 12, 60 and 300 tubes and the first rung evaluated, so the trail starts there. The converged count is 74 at 37 tubes a pass.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Read the studio trail as steps rather than as four numbers. What do the steps show, and why is no tolerance needed?', '["The steps shrink by a fixed ratio, which is the contraction factor, and the loop stops once that ratio is below the tolerance.", "The steps shrink, which is the contraction made visible, and the count is a whole number, so the loop lands on an answer and repeats it.", "The steps alternate in direction and shrink, so the answer is bracketed and the loop stops when the bracket closes.", "The steps shrink until the change is below one tube, at which point the count is rounded and the loop stops."]'::jsonb, 1, 'From 2 to 60 is a long way, 60 to 72 much shorter and 72 to 74 shorter again. Then it stops, because the count it produced is the count it was given.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 10, 'ORON runs the same chain on a four-pass bundle. What is its trail, and what does it end on?', '["4, 56 and 64 tubes, converged in 3 passes, at 16 tubes a pass.", "4, 24 and 64 tubes, converged in 3 passes, at 16 tubes a pass.", "4, 56, 64 and 64 tubes, converged in 4 passes, at 16 tubes a pass.", "4, 56 and 64 tubes, converged in 3 passes, at 37 tubes a pass."]'::jsonb, 0, 'ORON needs 330.327560 ft2, one of its tubes carries 5.235988 ft2, and its 64 tubes carry 335.103216 ft2, which is 1.445734 percent above the surface asked for.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 11, 'The studio screen also shows a Reynolds number of 44051.846000, a Prandtl number of 15.119375, a regime of turbulent and an inside film coefficient of 547.762384. What is a reader of this tier to do with them?', '["Use the film coefficient in place of the overall coefficient, since the tube side is the term the surface is referred to.", "Treat them as diagnostics of the loop, since they are what the iteration is actually converging on rather than the count.", "Check them against the count, since a Reynolds number and a tube count are two statings of the same quantity.", "Read them as real answers that the chain of this tier does not need, and meet them properly in the tier that assembles the coefficient."]'::jsonb, 3, 'They are listed so the screen is not a surprise and so a reader can see where the next two tiers pick the story up. The chain of this tier runs without them.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 12, 'The studio screen reports a controlling resistance of outsideFilm with insideFouling as its runner up and a margin of 51.612903 percent between them. What is that margin there for?', '["It says how much of the total resistance the leading term carries on its own, which is the thing that makes it the controlling one.", "It says how much the overall coefficient would improve if the leading term were taken out of the resistance stack entirely.", "It says how far the leading term leads the next one, so a one-word verdict is not read as though it were decided by a coin toss.", "It says how far the dirty coefficient sits below the clean one, which is what the fouling allowances cost."]'::jsonb, 2, 'Naming the largest resistance is the point of assembling a coefficient from parts, because that is the term worth spending money on. The parts themselves belong to the next tier.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 13, 'The studio reading is worked from a hot inlet of 300 F, a cold inlet of 100 F and a coefficient this tier takes as given. Which other figures behind it were chosen by a person rather than computed?', '["The two mass flows, the two heat capacities, the hot outlet, the tube geometry and the passes.", "The two capacity rates, the duty, the hot outlet and the passes, with everything below them computed.", "The two mass flows, the two heat capacities, the hot outlet and the correction factor of 1.000000.", "The two mass flows, the two heat capacities and the coefficient, with the hot outlet computed from the duty."]'::jsonb, 0, 'Everything else was computed. The correction factor is one because the arrangement is counter, and that is the engine deciding rather than anybody typing.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Six figures in a reading are worth checking against another person''s work. What do they have in common, and which figure is deliberately left off that list?', '["All six come from a single door, so one call reproduces them. The bundle diameter is left off, because it is built from constants the module cannot source.", "All six are continuous, so a comparison has a middle and can be close. The tube count is left off, because a comparison on a whole number is exact or out by a whole tube.", "All six are printed to six decimals, so a comparison is unambiguous. The duty is left off, because it is printed to four.", "All six are computed rather than chosen, so a disagreement is a real one. The coefficient is left off, because at this tier it is taken as given."]'::jsonb, 1, 'The duty, the cold outlet, the log mean, the surface required, the surface of one tube and the margin are the six. The count is the thing to understand and the margin is the thing to compare.'),
  ('heattransfer', 'beginner', 'module', 'm06-the-associate-reading', 15, 'A loop on some other case oscillates between two counts instead of settling. What does this tier say that tells you?', '["That the seed ladder was started on the wrong rung, and the next rung up will settle.", "That the film has landed in the band the module refuses, which is what an oscillation always means.", "Something about the case rather than about the arithmetic.", "That the tolerance on the loop is too tight for a count that rounds twice."]'::jsonb, 2, 'A trail is a diagnostic as well as a demonstration. The loop is the one thing in this chain that cannot be understood a link at a time, which is why the tier ends on it.'),
  ('heattransfer', 'beginner', 'final', null, 1, 'A study asks this engine what shaft power the pump feeding the cold side will draw. Where does that question belong?', '["To the air cooler door, which is the one place in this module a machine and its power are worked out.", "To the Pipeline and Line Sizing engine, which owns everything about a line including what drives the fluid along it.", "To Rotating Equipment, which owns machine work. Nothing in this module computes it.", "To this module, through the overall coefficient door, since a pump duty is carried as one of its thirteen keys."]'::jsonb, 2, 'A fan turns up in this module and its power is one line of arithmetic. A study of a machine is somebody else''s engine.'),
  ('heattransfer', 'beginner', 'final', null, 2, 'Two of the seventeen exported names are callable and do not take a named-argument object. Which are they?', '["The air density, which is a leaf correlation, and the bundle constants, which take no argument at all.", "The capacity rate and the area, each of which takes a single number because its answer carries a single key.", "The declared constants and the declared bounds, which are read rather than called and so need no argument.", "The energy balance and the log mean, each of which takes its four terminal temperatures positionally."]'::jsonb, 0, 'Both exceptions are written down rather than left to be discovered. A contract with two documented holes in it is usable.'),
  ('heattransfer', 'beginner', 'final', null, 3, 'A panel renders the error string from a refusal and stops. What has that panel thrown away?', '["The named string itself, since the error key holds a code and the string sits on a second key beside it.", "Nothing, because a refusal in this module carries a message and no other key at all.", "The basis, which every refusal carries so that a caller can see which stating produced the state.", "On three of the twelve doors, the figures the engine computed before it refused."]'::jsonb, 3, 'On the crossing refusal those figures are the two implied outlet temperatures, which are what make a crossing duty obviously wrong to a reader who has not done the arithmetic.'),
  ('heattransfer', 'beginner', 'final', null, 4, 'A coefficient referred to the outside tube surface is carried into a calculation that expects one referred to a stated bore. How wrong is the result?', '["Wrong by the ratio of the two diameters squared, since the area of a surface goes as the square of its diameter.", "Wrong by the ratio of the two areas, which is why this module names its reference area on every answer.", "Not wrong at all, provided the fouling allowances were quoted on the same surface as the coefficient.", "Wrong only where the wall is thick, since the two surfaces converge as the wall thins towards nothing."]'::jsonb, 1, 'Two different numbers describe one physical exchanger, and the surface each is spread over is what separates them. The module prints its reference area on every single answer so a figure cannot travel without it.'),
  ('heattransfer', 'beginner', 'final', null, 5, 'Duties, capacity rates and the UA product are printed to four decimals in this course while temperatures and coefficients are printed to six. What does that difference record?', '["The accuracy each class of figure is known to, which is coarser for the large quantities.", "The precision the grader accepts on each class, which is what a course prints against.", "A reporting convention and nothing else, chosen so the arithmetic can be followed step by step.", "The number of digits the engine itself carries internally for each class of quantity."]'::jsonb, 2, 'Six decimals on a surface does not mean the surface is known that well. It means the arithmetic reproduces that far, which is what lets a reader find where their figure and the engine''s parted company.'),
  ('heattransfer', 'beginner', 'final', null, 6, 'Three of the seventeen exports are frozen tables rather than functions. What is on them?', '["The declared constants, the declared bounds, and the register of what the module records that it cannot source.", "The declared constants, the bundle constants, and the register of every item the module records that it cannot source.", "The declared bounds, the arrangements the module carries, and the tube passes it carries bundle constants for.", "The declared constants, the declared bounds, and the published cases the golden file is written from."]'::jsonb, 0, 'The third of those tables is the one to read when an answer says it depends on something the module cannot source, because that register is where such an item is recorded.'),
  ('heattransfer', 'beginner', 'final', null, 7, 'The word approach already carries a separation meaning and a compression meaning elsewhere in this module family. What does this course do about it?', '["It uses approach for the smaller of the two end differences and says so on first use.", "It names the quantity it wants instead, which is the log mean of the two end temperature differences.", "It uses approach only on the air cooler, where no other meaning of the word is in play.", "It defines approach as the gap between the log mean and the arithmetic mean of the same two ends."]'::jsonb, 1, 'Fouling is the other word with two meanings in this family, and the same discipline applies: check which quantity a document means before carrying a number out of it.'),
  ('heattransfer', 'beginner', 'final', null, 8, 'On the studio balance the basis reads hot outlet. Which figures did a person choose and which did the engine compute?', '["The duty was chosen and both of the outlet temperatures were computed, which is exactly what a basis of hot outlet records.", "The two outlets were chosen and the duty computed from whichever of them the engine found first.", "The hot outlet and the duty were both chosen, and the basis names which of the two the engine preferred.", "The hot outlet was chosen. The duty of 2750000.0000 Btu an hour and the cold outlet of 134.375000 degF were computed."]'::jsonb, 3, 'One input produced the other two, and afterwards the three are not independent. Reading the basis first is how a reader finds out which of the three a screen was driven from.'),
  ('heattransfer', 'beginner', 'final', null, 9, 'ORON''s hot stream is 74000.0000 lb an hour at 0.620000 Btu per lb per degF and its cold stream 112000.0000 at 0.990000. What are its two capacity rates?', '["45880.0000 on the hot side and 110880.0000 on the cold, both in Btu an hour.", "27500.0000 and 80000.0000 Btu an hour per degF.", "45880.0000 on the hot side and 110880.0000 on the cold, both in Btu an hour per degF.", "74000.0000 and 112000.0000 Btu an hour per degF, since the heat capacities are dimensionless ratios."]'::jsonb, 2, 'Both of those belong to ORON and to nothing else in this course. Its hot side is the smaller of the two, so the hot stream is the one that governs there.'),
  ('heattransfer', 'beginner', 'final', null, 10, 'Two saved studies of the studio case were made by two people and both show a duty of 2750000.0000 Btu an hour. What tells you afterwards how each of them reached it?', '["The basis key, which reads hot outlet, cold outlet or stated duty according to what was typed.", "Nothing does, because the three statings produce identical answers and identical keys on the studio case.", "The arrangement key, since each stating is reachable under one arrangement and not under the others.", "The order of the keys on the answer, which follows the order in which the engine worked the figures out."]'::jsonb, 0, 'The duty, the hot outlet and the cold outlet are three views of one state. The basis column is the only column that moves across the three statings.'),
  ('heattransfer', 'beginner', 'final', null, 11, 'A reader has ORON''s cold outlet of 167.515873 degF and the studio duty of 2750000.0000 Btu an hour on the same page. What may be done with the pair?', '["They may be divided, since a duty over a temperature is a capacity rate and the units of the two work out correctly.", "Nothing. The two cases share nothing but the method, so no figure from one belongs in an expression about the other.", "They may be compared, since both cases were run on the same engine at the same precision.", "They may be combined if both are converted to the same basis first, which on these two is the hot outlet."]'::jsonb, 1, 'The studio case, ORON and the published cases are separate exchangers. Their figures must never be mixed.'),
  ('heattransfer', 'beginner', 'final', null, 12, 'The studio capacity ratio is 0.343750. At which point in the chain this tier walks is it used?', '["At the log mean, where it decides which of the two pairings is formed from the four terminals.", "At the area, where the duty is divided by it along with the coefficient and the driving force.", "At the tube count, where it fixes how many passes the governing stream needs.", "At no point. Sizing needs a duty, a driving force and a coefficient, and a rating is where a capacity ratio is wanted."]'::jsonb, 3, 'It is 27500.0000 over 80000.0000, the smaller capacity rate over the larger, which is why it is never above one. This tier stops at identifying the governing stream.'),
  ('heattransfer', 'beginner', 'final', null, 13, 'Two streams of different fluids arrive at the same capacity rate. How do they behave in the equations of this module?', '["Identically, since one product is all that survives into every expression downstream of the balance.", "Differently, because the fluid is carried alongside the rate and reaches the film and the fouling allowance.", "Identically in the balance and differently in the log mean, which is formed on the terminals rather than the rates.", "Differently, because the heat capacity is re-read at the outlet temperature of each stream."]'::jsonb, 0, 'A lot of a fluid with a small heat capacity and a little of one with a large heat capacity are the same stream to this balance.'),
  ('heattransfer', 'beginner', 'final', null, 14, 'The studio duty is 2750000.0000 Btu an hour and the cold capacity rate is 80000.0000 Btu an hour per degF. With a cold inlet of 100 F, where does the cold stream leave?', '["132.812500 degF.", "165.000000 degF.", "134.375000 degF.", "167.515873 degF."]'::jsonb, 2, 'The heat leaving the hot side has nowhere else to go, so the cold rise is that duty over that capacity rate. 167.515873 degF is where the cold stream leaves on ORON, which is a different exchanger.'),
  ('heattransfer', 'beginner', 'final', null, 15, 'What is the difference between the refusal of a duty that crosses the streams and the refusal of a duty parallel flow cannot deliver?', '["The first of the two carries its evidence on two keys and the second carries only a message, because a crossing is the harder of the two states to show a reader.", "The first has nothing to offer, because the duty asked for more than the two inlets allow. The second ends by naming the arrangement that can deliver it.", "The first is checked before any of the arithmetic has been done and the second after it, which is the reason only the second of them quotes temperatures.", "The first names the two inlet temperatures and the second names the two capacity rates, which is what each one tests against."]'::jsonb, 1, 'A bigger exchanger makes a crossing worse. The parallel state is impossible only for the arrangement that was asked about, and a counter-current unit delivers the same duty.'),
  ('heattransfer', 'beginner', 'final', null, 16, 'On the parallel refusal at 5200000 Btu an hour the evidence keys read 110.909091 and 165.000000 degF. What are those two figures?', '["The two end differences the parallel pairing would form on these terminals, handed back so that the crossing can be seen.", "The nearest pair of outlet temperatures a parallel unit could actually reach, which is how far the study would have to move.", "The two inlet temperatures the duty was tested against, quoted so a reader can see which one was breached.", "The two temperatures the requested duty implies, which a counter-current unit at that same duty actually delivers."]'::jsonb, 3, 'Both figures existed before the parallel test ran. That test looks at the ordering of the two outlets and at nothing else, which is why one word in the call decides between a number and a refusal.'),
  ('heattransfer', 'beginner', 'final', null, 17, 'Where in the sequence do the two wrong-way outlet guards and the zero duty guard run, and what follows from that?', '["Before any arithmetic at all, so each message can quote only the inputs, which is exactly what has to be changed.", "After the duty has been formed, so each message can quote the duty the wrong-way input produced.", "After the outlets have been formed and before the log mean, so a bad terminal cannot reach a driving force.", "At the area door, which is the first door in the chain able to see all four terminals at once."]'::jsonb, 0, 'A guard that runs after the computation is a guard on a number that has already been used, and by then the wrong value may have reached a log mean or an area.'),
  ('heattransfer', 'beginner', 'final', null, 18, 'Four states are put to the energy balance on the studio streams. Which one is answered rather than refused?', '["A duty of 5200000 Btu an hour asked for under parallel flow.", "A stated duty of 0 under either of those two arrangements.", "A duty of 5200000 Btu an hour asked for under counter-current flow.", "A duty of 5200000 Btu an hour asked for under an arrangement of crossflow."]'::jsonb, 2, 'One duty, three ways of asking, and only one of them is a question this module will take. The answer is 5200000.0000 Btu an hour with the streams leaving at 110.909091 and 165.000000 degF.'),
  ('heattransfer', 'beginner', 'final', null, 19, 'An arrangement of crossflow is asked for. What does the message say, and why does it say both halves?', '["It names counter, parallel and shell1 and offers the nearest of the three, so a caller can accept or refuse the substitution.", "It names counter, parallel and shell1 and states that it will not fall back to one of them, so the list saves a trip and the policy tells you something about every other answer.", "It names the arrangement given and the door that refused it, so a caller can find the check in the source.", "It names counter, parallel and shell1 and states that cross flow belongs to the air cooler, which is a cross-flow machine."]'::jsonb, 1, 'A defaulted input is worse than a refused one, because a default answers a question the caller did not ask and never says it did.'),
  ('heattransfer', 'beginner', 'final', null, 20, 'The teaching digest lists the states this balance will not compute. How many are there, and what do they have in common?', '["Three, and every one of them is a temperature that moved in the wrong direction on one of the two streams.", "Twelve, one for each door of the module, since each door carries exactly one guard of its own.", "Six, and every one of them is caught after the duty has been formed, which is what lets each message quote it.", "Six, and every one of them is a state a saved study can carry, with each refusal naming the box rather than the physics."]'::jsonb, 3, 'A wrong-way hot outlet, a wrong-way cold outlet, a duty of zero, a duty disagreeing with a stated outlet, a duty that crosses the streams, and a duty parallel flow cannot deliver.'),
  ('heattransfer', 'beginner', 'final', null, 21, 'What makes a negative duty a dangerous thing for a balance to let through?', '["It prints perfectly well, so it reads in a report as a sign convention rather than as a mistake.", "It stops the chain at the next door, so the work done up to that point is lost.", "It reverses the pairing the log mean forms, so the driving force comes back on the wrong two ends.", "It is rejected by the tube count rather than by the balance, so the message names the wrong box."]'::jsonb, 0, 'A wrong-way hot outlet would produce one, and with it a cold outlet below the cold inlet. Every one of those figures renders on a page like any other.'),
  ('heattransfer', 'beginner', 'final', null, 22, 'ORON''s counter-current ends are 177.484127 and 113.000000 degF. Its log mean is 142.824087 degF and the arithmetic mean of those ends is 145.242063 degF. Which of these is a check a reader can make without a reference?', '["That the two ends differ by less than half of either, which is the band the closed form is fitted over.", "That the log mean is half the sum of the two ends less the logarithm of their ratio, which anyone can recompute.", "That the log mean sits below the arithmetic mean, which is an analytic limit at unequal ends.", "That the arithmetic mean sits below the larger end, which is what makes the pairing counter-current."]'::jsonb, 2, 'The limit is immune to an error made in both the engine and the file it is checked against, because nothing in the code was consulted to derive it.'),
  ('heattransfer', 'beginner', 'final', null, 23, 'The parallel ends on the studio case are 200.000000 and 65.625000 degF. Which terminals meet at each of those two ends?', '["The hot inlet meets the cold outlet at the first and the hot outlet meets the cold inlet at the second.", "The two inlets meet at the first and the two outlets meet at the second, because both streams enter at one end and leave at the other.", "The two temperatures of the hot stream meet at the first and the two of the cold stream meet at the second.", "The widest available pair of the four terminals forms the first, and whatever two are left form the second."]'::jsonb, 1, 'So 300 F faces 100.000000 degF, which is 200.000000 degF, and 200.000000 degF faces 134.375000 degF, which is 65.625000 degF. One end got wider and the other got much narrower.'),
  ('heattransfer', 'beginner', 'final', null, 24, 'Published case 5 has ends of 60.000000 and 80.000000 degF and a log mean of 69.521190 degF against an arithmetic mean of 70.000000 degF. What does this row add to the table?', '["That the limit holds whichever way round the two ends are written, since here the first end is the smaller one.", "That the two means come together once the smaller end is above half the larger, which is what this row is here to show.", "That a log mean is defined only where the first end is the larger, so this row is reported in the other order.", "That ends this close make the two means agree to the precision this course prints at."]'::jsonb, 0, 'The two means are 69.521190 and 70.000000 degF here, so they are visibly different. Equality needs the two ends to be the same number, which is published case 3 at 280.000000 degF.'),
  ('heattransfer', 'beginner', 'final', null, 25, 'The equal-ends flag reads yes on published case 3, where the log mean comes back as 280.000000 degF. What has the module done there?', '["Evaluated the closed form as usual, since the ratio of two equal ends is one and its logarithm is well defined.", "Returned the arithmetic mean of the two ends instead, which at equal ends agrees with the log mean.", "Refused the general branch and fallen back to the counter-current pairing, which is what the flag records.", "Handled the case directly rather than letting the closed form divide zero by zero, and said so on the answer."]'::jsonb, 3, 'Its golden figure is 280.000000 degF as well, which is an integration and a closed form agreeing at the one point where the closed form had to do something different.'),
  ('heattransfer', 'beginner', 'final', null, 26, 'A caller wants the corrected driving force of a 1-2 shell unit and has the 130.064846 degF the shell reading gave. What is still to be done to it?', '["Nothing at all, since the correction was applied inside the door that returned the figure.", "Re-read it under the parallel pairing and take the mean of the two figures.", "Multiply it by a correction factor, which is at or below one and which belongs to the tier after this one.", "Divide it by the number of shell passes the unit is built with."]'::jsonb, 2, 'A factor at or below one can only take the corrected figure to or below 130.064846 degF, which is why using the shell reading directly undersizes a surface.'),
  ('heattransfer', 'beginner', 'final', null, 27, 'Your log mean disagrees with the engine''s on a case you are checking. Which keys on the answer do you compare first?', '["The log mean and the basis, since a figure and the method that produced it are what a comparison is between.", "The two end differences, since the pairing is where a disagreement usually sits and the mean itself is hard to get wrong once its inputs agree.", "The equal-ends flag, since a case that took the special branch cannot be compared against one that did not.", "The four terminal temperatures the door was given, since they are the only inputs a reader supplies."]'::jsonb, 1, 'One subtraction, one division and one logarithm stand between two agreed ends and a log mean. The two end keys let a reader find the disagreement in one glance.'),
  ('heattransfer', 'beginner', 'final', null, 28, 'Which statement about a log mean can be checked with no reference and no file at all?', '["That it sits below the arithmetic mean of its own two ends whenever those two ends differ.", "That it sits above the arithmetic mean of its own two ends whenever those two ends differ.", "That it may stand in for the arithmetic mean wherever the two ends are within about ten degF of each other.", "That it is fixed by the two inlet temperatures alone, which is why one case can carry two of them."]'::jsonb, 0, 'It is an analytic limit. That is what makes it immune to an error made in an engine and in the file that checks the engine, which would leave those two agreeing and both wrong.'),
  ('heattransfer', 'beginner', 'final', null, 29, 'The studio case has a duty of 2750000.0000 Btu an hour, a coefficient of 92.110348, a correction factor of 1.000000 and a log mean of 130.064846 degF. What surface does it need?', '["232.477856 ft2.", "157.246707 ft2.", "229.543151 ft2.", "286.311271 ft2."]'::jsonb, 2, 'The duty divided by the other three. The 232.477856 ft2 figure is the surface 74 tubes actually carry, and 157.246707 ft2 is what the clean coefficient would ask for.'),
  ('heattransfer', 'beginner', 'final', null, 30, 'ORON needs 330.327560 ft2, one of its tubes carries 5.235988 ft2 and its bundle runs four passes. What count comes back and what surface does it carry?', '["16 tubes, carrying 335.103216 ft2, which is the count each of the four passes carries.", "64 tubes, carrying 335.103216 ft2.", "64 tubes, carrying 330.327560 ft2, since the count is chosen to land on the surface asked for.", "232 tubes, carrying 1214.749159 ft2, which is the four-pass row in the published cases."]'::jsonb, 1, 'The surface over the per-tube figure is rounded up to a whole tube and then up to a whole multiple of the four passes, which gives 16 tubes a pass and an overshoot of 1.445734 percent.'),
  ('heattransfer', 'beginner', 'final', null, 31, 'Published case 1 on the area door has a correction factor of 0.900000 and reaches 578.703704 ft2. What is special about that factor on that row?', '["It was computed from the two dimensionless groups, which is what makes the row worth publishing.", "It is the smallest factor the module will accept, since the band is closed at one on both sides.", "It was measured from the golden figure by dividing the published area into the duty.", "It was given rather than computed, and it is the only row in that table below one."]'::jsonb, 3, 'The other three rows in that table carry a correction factor of 1.000000, which drops out of the division entirely.'),
  ('heattransfer', 'beginner', 'final', null, 32, 'A tube count is asked for at 3 passes. What comes back?', '["A refusal naming what the module carries, which is bundle constants for 1, 2, 4 and 6 tube passes.", "An answer at 3 passes, with the bundle diameter omitted because no constants are carried for it.", "A refusal naming the tube count, since a count that 3 divides is what the door would need.", "An answer rounded to 4 passes, with a note saying the pass count was moved to one that is carried."]'::jsonb, 0, 'The module carries bundle constants for four pass counts and refuses the rest rather than rounding to a neighbour.'),
  ('heattransfer', 'beginner', 'final', null, 33, 'Published case 2 asks for 2000.000000 ft2 on tubes of 3.141593 ft2 in two passes. What count comes back, and how is it split?', '["638 tubes, at 320 a pass.", "160 tubes, at 80 a pass.", "638 tubes, at 319 a pass.", "274 tubes, at 137 a pass."]'::jsonb, 2, 'Its 638 tubes carry 2004.336113 ft2, which is 0.216806 percent above the surface asked for. The golden file carries the same count, written by the oracle on its own route.'),
  ('heattransfer', 'beginner', 'final', null, 34, 'The studio case carries 3.141593 ft2 a tube and ORON carries 5.235988 ft2 a tube. What sets that figure?', '["The outside diameter, the length and the pass count, since a pass count divides the bundle into equal groups.", "The outside diameter and the length of the tube, and nothing else at all.", "The outside diameter, the length and the layout angle the bundle constants are carried at.", "The bore and the length, since the tube-side film is what the surface of a tube is referred to."]'::jsonb, 1, 'Pi times the outside diameter in feet times the length. Nothing about the duty, the streams or the coefficient reaches it, which is why only two values appear across seven cases.'),
  ('heattransfer', 'beginner', 'final', null, 35, 'Published case 3 overshoots by 1.229097 percent on a four-pass bundle and published case 4 by 0.092603 percent on a two-pass one. What is doing the work in that difference?', '["Where the unrounded figure fell, and how far the second rounding then had to lift the count, which on four passes can be further than on two.", "The size of the bundle, since 232 tubes is the smaller of the two counts and a smaller bundle overshoots more.", "The per-tube surface, since 5.235988 ft2 a tube is the larger of the two and a larger tube always leaves a larger remainder.", "The duty each of the two rows carries, since a four-pass bundle is given the larger duty and a margin is reported as a share of whatever duty went in."]'::jsonb, 0, 'Published case 3 asks for 1200.000000 ft2 on tubes of 5.235988 ft2 and its 232 tubes carry 1214.749159 ft2, which is more surplus surface than one extra tube would add. Rounding up to a multiple of four can lift a count further than rounding up to a multiple of two.'),
  ('heattransfer', 'beginner', 'final', null, 36, 'On ORON the coefficient is 106.971929, the surface required is 330.327560 ft2, the correction factor is 1.000000 and the log mean is 142.824087 degF. Multiply the four. What does the result show?', '["5046800.0000 Btu an hour, the duty, so the tube count on ORON has been confirmed against the golden file.", "5046800.0000 Btu an hour, the duty, so the coefficient has been checked by a second and independent method.", "5046800.0000 Btu an hour, the duty, so ORON''s chain closes on itself the way the studio case does.", "A figure above the duty by the overshoot, because the surface used here is the one the bundle carries rather than the one asked for."]'::jsonb, 2, 'A self-consistency check is the same equation run backwards. It catches a screen whose figures were left behind by an input that moved, and it is not evidence that any one of them is right.'),
  ('heattransfer', 'beginner', 'final', null, 37, 'Put the steps of the Associate reading in the order they are worked.', '["The duty, the capacity rates, the surface, the driving force, the loop, then the tubes.", "The capacity rates, the driving force, the duty, the tubes, the surface, then the loop.", "The duty, the driving force, the capacity rates, the surface, the loop, then the tubes.", "The capacity rates, the duty, the driving force, the surface, the tubes, then the loop."]'::jsonb, 3, 'Each step consumes what the one above it produced. The loop comes last because it is the one thing in the chain that cannot be understood a link at a time.'),
  ('heattransfer', 'beginner', 'final', null, 38, 'The studio trail runs 2, 60, 72, 74 in four passes and ORON''s runs 4, 56, 64 in three. What does the difference in pass counts mean?', '["That ORON''s loop is better conditioned, since a contraction that settles sooner has the smaller contraction factor.", "Only that the two cases took different numbers of steps to land on a count that repeats itself.", "That ORON started nearer its answer, since its first rung is 4 and the studio ladder starts at 2.", "That the studio case passed through a count the film refused and had to take an extra step around it."]'::jsonb, 1, 'Both trails start on the first rung of their own ladder, and both stop when the count produced is the count that went in.'),
  ('heattransfer', 'beginner', 'final', null, 39, 'Which figure in the Associate chain does this tier take as given, and what does the next tier build it out of?', '["The correction factor, which the next tier computes from two dimensionless temperature groups.", "The log mean, which the next tier replaces with a corrected driving force on a shell exchanger.", "The overall coefficient, which the next tier assembles from five named resistances in series.", "The tube count, which the next tier closes as a loop against the tube-side film."]'::jsonb, 2, 'The correction factor was also handed over, at 1.000000, and the next tier is where it stops being one. All five resistances are referred to the outside tube surface.'),
  ('heattransfer', 'beginner', 'final', null, 40, 'This course asks three questions of every figure on a screen. What are they?', '["Did the engine compute it, did you choose it, or did the engine decline to invent it.", "Is it an input, is it an output, or is it a note attached to one of the two.", "Is it measured, is it fitted, or is it declared by the module without a source.", "Did it come from the studio, from the golden file, or from the oracle behind the golden."]'::jsonb, 0, 'Heat transfer goes wrong when those three get mixed up, and a fouling allowance somebody typed starts being read as a measurement.'),
  ('heattransfer', 'beginner', 'final', null, 41, 'The studio screen shows P at 0.171875 and R at 2.909091 while this tier walks its chain. What are they doing there?', '["Setting the correction factor of 1.000000 that this tier uses, which is why they appear beside it.", "Reporting the capacity ratio in its two directions, hot over cold and cold over hot.", "Carrying the arrangement, since a shell exchanger is identified by the pair of groups it runs at.", "Waiting for the next tier, which is where a correction factor is built out of them."]'::jsonb, 3, 'They sat on the screen in this tier''s last module without being used. The letter P here is a dimensionless temperature group and nothing else.'),
  ('heattransfer', 'beginner', 'final', null, 42, 'What actually closes the loop on the studio case?', '["The count reaching a whole multiple of the pass count, which is what the second rounding is for.", "The converged count of 74 tubes reproducing itself when it is fed back through the film, the coefficient and the area.", "The self-consistency check reproducing the duty, which is what tells the studio to stop iterating.", "The trail reaching the third rung of the seed ladder, which is where the studio stops walking it."]'::jsonb, 1, 'The loop stops because the count it produced is the count it was given. A count is a whole number, so the iteration lands on an answer rather than creeping towards one.');
